def test_bruteforce_windows(run, x):
    p = list(map(int, x.split()[1:]))
    total = 0
    for left in range(len(p)):
        for right in range(left + 1, len(p)):
            total += sorted(p[left:right + 1])[-2]
    out = run(x)
    assert out.strip() == str(total)

def test_incremental_two_largest(run, x):
    p = list(map(int, x.split()[1:]))
    total = 0
    for left in range(len(p) - 1):
        largest = second = 0
        for right in range(left, len(p)):
            value = p[right]
            if value > largest:
                second, largest = largest, value
            elif value > second:
                second = value
            if right > left:
                total += second
    out = run(x)
    assert out.strip() == str(total)

def test_reverse_rank_oracle(run, x):
    p = list(map(int, x.split()[1:]))
    expected = sum(
        sorted(p[left:right + 1], reverse=True)[1]
        for left in range(len(p))
        for right in range(left + 1, len(p))
    )
    out = run(x)
    assert out.strip() == str(expected)

def test_interval_endpoint_enumeration(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for right in range(1, len(p)):
        for left in range(right):
            values = sorted(p[left:right + 1])
            expected += values[-2]
    out = run(x)
    assert out.strip() == str(expected)

def test_slice_sort_oracle(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for left in range(len(p)):
        for right in range(left + 1, len(p)):
            interval = list(p[left:right + 1])
            interval.sort()
            expected += interval[len(interval) - 2]
    out = run(x)
    assert out.strip() == str(expected)

def test_pairwise_range_oracle(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for left, right in ((a, b) for a in range(len(p)) for b in range(a + 1, len(p))):
        expected += sorted(p[left:right + 1])[-2]
    out = run(x)
    assert out.strip() == str(expected)

def test_explicit_rank_scan(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for left in range(len(p)):
        for right in range(left + 1, len(p)):
            first = 0
            second = 0
            for value in p[left:right + 1]:
                if value > first:
                    second = first
                    first = value
                elif value > second:
                    second = value
            expected += second
    out = run(x)
    assert out.strip() == str(expected)

def test_all_left_endpoints(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for left in range(0, len(p) - 1):
        for right in range(left + 1, len(p)):
            ordered = sorted(p[left:right + 1])
            expected += ordered[-2]
    out = run(x)
    assert out.strip() == str(expected)

def test_output_total(run, x):
    p = list(map(int, x.split()[1:]))
    total = 0
    for left in range(len(p)):
        for right in range(left + 1, len(p)):
            total += sorted(p[left:right + 1])[-2]
    out = run(x)
    assert out.strip() == str(total)

def test_complete_small_enumeration(run, x):
    p = list(map(int, x.split()[1:]))
    contributions = []
    for left in range(len(p) - 1):
        for right in range(left + 1, len(p)):
            values = p[left:right + 1]
            contributions.append(sorted(values)[-2])
    out = run(x)
    assert out.strip() == str(sum(contributions))

def test_delete_bruteforce(run, x):
    a = list(map(int, x.split()[1:]))
    best = min(max(b[i + 1] - b[i] for i in range(len(b) - 1)) for b in (a[:k] + a[k + 1:] for k in range(1, len(a) - 1)))
    assert run(x).strip() == str(best)

def test_gap_merge(run, x):
    a = list(map(int, x.split()[1:]))
    gaps = [a[i + 1] - a[i] for i in range(len(a) - 1)]
    values = []
    for k in range(1, len(a) - 1):
        remaining = gaps[:k - 1] + [a[k + 1] - a[k - 1]] + gaps[k + 1:]
        values.append(max(remaining))
    assert run(x).strip() == str(min(values))

def test_pair_scan(run, x):
    a = list(map(int, x.split()[1:]))
    answer = 10**9
    for skip in range(1, len(a) - 1):
        previous = None
        worst = 0
        for i, value in enumerate(a):
            if i != skip:
                if previous is not None:
                    worst = max(worst, value - previous)
                previous = value
        answer = min(answer, worst)
    assert run(x).strip() == str(answer)

def test_candidate_tracks(run, x):
    a = list(map(int, x.split()[1:]))
    candidates = []
    for removed in range(1, len(a) - 1):
        track = [value for i, value in enumerate(a) if i != removed]
        candidates.append(max(track[i + 1] - track[i] for i in range(len(track) - 1)))
    assert run(x).strip() == str(min(candidates))

def test_local_join(run, x):
    a = list(map(int, x.split()[1:]))
    result = 10**9
    for removed in range(1, len(a) - 1):
        worst = 0
        for i in range(len(a) - 1):
            if i == removed - 1:
                worst = max(worst, a[removed + 1] - a[removed - 1])
            elif i != removed:
                worst = max(worst, a[i + 1] - a[i])
        result = min(result, worst)
    assert run(x).strip() == str(result)

def test_max_after_skip(run, x):
    a = list(map(int, x.split()[1:]))
    scores = []
    for skipped in range(1, len(a) - 1):
        kept = a[:skipped] + a[skipped + 1:]
        scores.append(max(kept[i] - kept[i - 1] for i in range(1, len(kept))))
    assert run(x).strip() == str(min(scores))

def test_retained_neighbors(run, x):
    a = list(map(int, x.split()[1:]))
    expected = 10**9
    for omitted in range(1, len(a) - 1):
        retained = []
        for i in range(len(a)):
            if i != omitted:
                retained.append(a[i])
        difficulty = max(retained[i] - retained[i - 1] for i in range(1, len(retained)))
        expected = min(expected, difficulty)
    assert run(x).strip() == str(expected)

def test_all_removals(run, x):
    a = list(map(int, x.split()[1:]))
    answer = None
    for removed in range(1, len(a) - 1):
        last = a[0]
        worst = 0
        for i in range(1, len(a)):
            if i != removed:
                worst = max(worst, a[i] - last)
                last = a[i]
        answer = worst if answer is None else min(answer, worst)
    assert run(x).strip() == str(answer)

def test_minimax(run, x):
    a = list(map(int, x.split()[1:]))
    expected = min(
        max(a[v] - a[u] for u, v in zip(indices, indices[1:]))
        for removed in range(1, len(a) - 1)
        for indices in ([i for i in range(len(a)) if i != removed],)
    )
    assert run(x).strip() == str(expected)

def test_definition_oracle(run, x):
    a = list(map(int, x.split()[1:]))
    difficulties = []
    for removed in range(1, len(a) - 1):
        previous = a[0]
        difficulty = 0
        for i in range(1, len(a)):
            if i == removed:
                continue
            difficulty = max(difficulty, a[i] - previous)
            previous = a[i]
        difficulties.append(difficulty)
    assert run(x).strip() == str(min(difficulties))

