def test_directional_bruteforce(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    y, z = i + di, j + dj
                    while 0 <= y < n and 0 <= z < m:
                        if g[y][z] == 1:
                            want += 1
                            break
                        y, z = y + di, z + dj
    assert run(x).strip() == str(want)

def test_row_segments(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                want += any(g[i][k] == 1 for k in range(j))
                want += any(g[i][k] == 1 for k in range(j + 1, m))
                want += any(g[k][j] == 1 for k in range(i))
                want += any(g[k][j] == 1 for k in range(i + 1, n))
    assert run(x).strip() == str(want)

def test_prefix_rays(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        seen = False
        for j in range(m):
            if g[i][j] == 0 and seen:
                want += 1
            seen = seen or g[i][j] == 1
        seen = False
        for j in range(m - 1, -1, -1):
            if g[i][j] == 0 and seen:
                want += 1
            seen = seen or g[i][j] == 1
    for j in range(m):
        seen = False
        for i in range(n):
            if g[i][j] == 0 and seen:
                want += 1
            seen = seen or g[i][j] == 1
        seen = False
        for i in range(n - 1, -1, -1):
            if g[i][j] == 0 and seen:
                want += 1
            seen = seen or g[i][j] == 1
    assert run(x).strip() == str(want)

def test_explicit_steps(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                for di, dj in ((0, -1), (0, 1), (-1, 0), (1, 0)):
                    for step in range(1, max(n, m)):
                        y, z = i + di * step, j + dj * step
                        if not (0 <= y < n and 0 <= z < m):
                            break
                        if g[y][z] == 1:
                            want += 1
                            break
    assert run(x).strip() == str(want)

def test_boolean_sides(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = sum(
        bool(any(g[i][k] for k in range(j))) +
        bool(any(g[i][k] for k in range(j + 1, m))) +
        bool(any(g[k][j] for k in range(i))) +
        bool(any(g[k][j] for k in range(i + 1, n)))
        for i in range(n) for j in range(m) if g[i][j] == 0
    )
    assert run(x).strip() == str(want)

def test_transposed_scan(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i, row in enumerate(g):
        for j, value in enumerate(row):
            if value == 0:
                want += 1 in row[:j]
                want += 1 in row[j + 1:]
                col = [g[k][j] for k in range(n)]
                want += 1 in col[:i]
                want += 1 in col[i + 1:]
    assert run(x).strip() == str(want)

def test_ray_generators(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                rays = (
                    ((i, k) for k in range(j - 1, -1, -1)),
                    ((i, k) for k in range(j + 1, m)),
                    ((k, j) for k in range(i - 1, -1, -1)),
                    ((k, j) for k in range(i + 1, n)),
                )
                want += sum(any(g[y][z] == 1 for y, z in ray) for ray in rays)
    assert run(x).strip() == str(want)

def test_output_bounds(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    out = run(x).strip()
    empty = sum(value == 0 for row in g for value in row)
    assert out.isdigit() and 0 <= int(out) <= 4 * empty

def test_cellwise_direction_count(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if not g[i][j]:
                directions = ((0, -1), (0, 1), (-1, 0), (1, 0))
                for di, dj in directions:
                    y, z = i + di, j + dj
                    visible = False
                    while 0 <= y < n and 0 <= z < m:
                        visible = visible or g[y][z] == 1
                        y, z = y + di, z + dj
                    want += visible
    assert run(x).strip() == str(want)

def test_reverse_and_forward_rays(run, x):
    g = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if g[i][j] == 0:
                want += any(g[i][k] for k in range(j - 1, -1, -1))
                want += any(g[i][k] for k in range(j + 1, m))
                want += any(g[k][j] for k in range(i - 1, -1, -1))
                want += any(g[k][j] for k in range(i + 1, n))
    assert run(x).strip() == str(want)

def test_exhaustive_pairs(run, x):
    l, r = map(int, x.split())
    parts = run(x).split()
    assert len(parts) == 1
    assert parts[0].isdecimal()
    got = int(parts[0])
    assert 0 <= got < 1000000007
    if r - l <= 64:
        want = sum(1 for a in range(l, r + 1) for b in range(a, r + 1) if b % a == (b ^ a))
        assert got == want % 1000000007

def test_small_pair_sum(run, x):
    l, r = map(int, x.split())
    parts = run(x).split()
    assert len(parts) == 1
    assert parts[0].isdecimal()
    got = int(parts[0])
    assert 0 <= got < 1000000007
    if r - l <= 64:
        want = 0
        for y in range(l, r + 1):
            for a in range(l, y + 1):
                want += (y % a == (y ^ a))
        assert got == want % 1000000007

def test_diagonal_singleton(run, x):
    l, r = map(int, x.split())
    parts = run(x).split()
    assert len(parts) == 1
    assert parts[0].isdecimal()
    got = int(parts[0])
    assert 0 <= got < 1000000007
    if l == r:
        assert got == 1
    elif r - l <= 64:
        want = sum(1 for a in range(l, r + 1) for b in range(a, r + 1) if b % a == (b ^ a))
        assert got == want % 1000000007

def test_short_interval_count(run, x):
    l, r = map(int, x.split())
    parts = run(x).split()
