def test_exact_events(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key not in red:
            if card == 'r' or (card == 'y' and key in yellow):
                red.add(key); expected.extend((teams[side], player, t))
            else:
                yellow.add(key)
    assert run(x).split() == expected

def test_output_rows(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key in red:
            continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append([teams[side], player, t])
        else:
            yellow.add(key)
    assert [line.split() for line in run(x).splitlines() if line.split()] == expected

def test_event_count(run, x):
    p = x.splitlines(); yellow = set(); red = set(); count = 0
    for line in p[3:]:
        _, side, player, card = line.split(); key = (side, player)
        if key not in red:
            if card == 'r' or (card == 'y' and key in yellow):
                red.add(key); count += 1
            else:
                yellow.add(key)
    assert len(run(x).split()) == 3 * count

def test_event_minutes(run, x):
    p = x.splitlines(); yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key in red:
            continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append(t)
        else:
            yellow.add(key)
    assert run(x).split()[2::3] == expected

def test_event_teams(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = []
    for line in p[3:]:
        _, side, player, card = line.split(); key = (side, player)
        if key in red:
            continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append(teams[side])
        else:
            yellow.add(key)
    assert run(x).split()[::3] == expected

def test_event_players(run, x):
    p = x.splitlines(); yellow = set(); red = set(); expected = []
    for line in p[3:]:
        _, side, player, card = line.split(); key = (side, player)
        if key in red:
            continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected.append(player)
        else:
            yellow.add(key)
    assert run(x).split()[1::3] == expected

def test_ordered_records(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = []
    for line in p[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key not in red:
            if card == 'r' or (card == 'y' and key in yellow):
                red.add(key); expected.append((teams[side], player, t))
            else:
                yellow.add(key)
    out = run(x).split()
    assert list(zip(out[::3], out[1::3], out[2::3])) == expected

def test_no_duplicate_reds(run, x):
    p = x.splitlines(); teams = {'h': p[0], 'a': p[1]}; yellow = set(); red = set(); expected = {}
    for line in p[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key in red:
            continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); expected[(teams[side], player)] = t
        else:
            yellow.add(key)
    out = run(x).split()
    assert len(out) == 3 * len(expected) and {(out[i], out[i + 1]): out[i + 2] for i in range(0, len(out), 3)} == expected

def test_empty_output(run, x):
    p = x.splitlines(); yellow = set(); red = set(); count = 0
    for line in p[3:]:
        _, side, player, card = line.split(); key = (side, player)
        if key in red:
            continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); count += 1
        else:
            yellow.add(key)
    out = run(x).split()
    assert (not out) if count == 0 else len(out) == 3 * count

def test_team_player_minutes(run, x):
