tests_src:
def test_full_records(run, x):
    a = x.splitlines(); teams = {'h': a[0], 'a': a[1]}; yellow = set(); red = set(); want = []
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key not in red and (card == 'r' or (card == 'y' and key in yellow)):
            red.add(key); want.append([teams[side], player, t])
        elif key not in red and card == 'y': yellow.add(key)
    assert [line.split() for line in run(x).splitlines()] == want

def test_event_count(run, x):
    a = x.splitlines(); yellow = set(); red = set(); count = 0
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key not in red and (card == 'r' or (card == 'y' and key in yellow)):
            red.add(key); count += 1
        elif key not in red and card == 'y': yellow.add(key)
    assert len(run(x).splitlines()) == count

def test_record_tokens(run, x):
    a = x.splitlines(); teams = {'h': a[0], 'a': a[1]}; yellow = set(); red = set(); want = []
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key not in red and (card == 'r' or (card == 'y' and key in yellow)):
            red.add(key); want.append((teams[side], player, t))
        elif key not in red and card == 'y': yellow.add(key)
    assert [tuple(line.split()) for line in run(x).splitlines()] == want

def test_chronological_minutes(run, x):
    a = x.splitlines(); yellow = set(); red = set(); want = []
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key not in red and (card == 'r' or (card == 'y' and key in yellow)):
            red.add(key); want.append(t)
        elif key not in red and card == 'y': yellow.add(key)
    got = [line.split() for line in run(x).splitlines()]
    assert all(len(record) == 3 for record in got)
    assert [record[2] for record in got] == want

def test_team_player_order(run, x):
    a = x.splitlines(); teams = {'h': a[0], 'a': a[1]}; yellow = set(); red = set(); want = []
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key not in red and (card == 'r' or (card == 'y' and key in yellow)):
            red.add(key); want.append([teams[side], player])
        elif key not in red and card == 'y': yellow.add(key)
    got = [line.split() for line in run(x).splitlines()]
    assert all(len(record) == 3 for record in got)
    assert [record[:2] for record in got] == want

def test_first_red_only(run, x):
    a = x.splitlines(); teams = {'h': a[0], 'a': a[1]}; yellow = set(); sent = set(); want = []
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key in sent: continue
        if card == 'r' or (card == 'y' and key in yellow):
            sent.add(key); want.append([teams[side], player, t])
        elif card == 'y': yellow.add(key)
    assert [line.split() for line in run(x).splitlines()] == want

def test_second_yellow_rule(run, x):
    a = x.splitlines(); teams = {'h': a[0], 'a': a[1]}; yellow = set(); red = set(); want = []
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key in red: continue
        if card == 'y' and key in yellow:
            red.add(key); want.append([teams[side], player, t])
        elif card == 'y': yellow.add(key)
        elif card == 'r': red.add(key); want.append([teams[side], player, t])
    assert [line.split() for line in run(x).splitlines()] == want

def test_direct_red_rule(run, x):
    a = x.splitlines(); teams = {'h': a[0], 'a': a[1]}; yellow = set(); red = set(); want = []
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key in red: continue
        if card == 'r': red.add(key); want.append([teams[side], player, t])
        elif key in yellow: red.add(key); want.append([teams[side], player, t])
        else: yellow.add(key)
    assert [line.split() for line in run(x).splitlines()] == want

def test_output_shape(run, x):
    a = x.splitlines(); teams = {'h': a[0], 'a': a[1]}; yellow = set(); red = set(); want = []
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key not in red and (card == 'r' or (card == 'y' and key in yellow)):
            red.add(key); want.append([teams[side], player, t])
        elif key not in red and card == 'y': yellow.add(key)
    got = [line.split() for line in run(x).splitlines()]
    assert all(len(record) == 3 for record in got)
    assert got == want

def test_no_extra_events(run, x):
    a = x.splitlines(); teams = {'h': a[0], 'a': a[1]}; yellow = set(); red = set(); want = []
    for line in a[3:]:
        t, side, player, card = line.split(); key = (side, player)
        if key in red: continue
        if card == 'r' or (card == 'y' and key in yellow):
            red.add(key); want.extend([teams[side], player, t])
        else: yellow.add(key)
    assert run(x).split() == want

