def test_greedy_endpoint_simulation(run, x):
    v = list(map(int, x.split()))
    a = v[1:]
    l, r, s, d = 0, len(a) - 1, 0, 0
    for turn in range(len(a)):
        if a[l] > a[r]:
            pick = a[l]
            l += 1
        else:
            pick = a[r]
            r -= 1
        if turn % 2 == 0:
            s += pick
        else:
            d += pick
    assert run(x).split() == [str(s), str(d)]

def test_first_turn_assignment(run, x):
    v = list(map(int, x.split()))
    a = v[1:]
    left, right = 0, len(a) - 1
    scores = [0, 0]
    player = 0
    while left <= right:
        if a[left] > a[right]:
            scores[player] += a[left]
            left += 1
        else:
            scores[player] += a[right]
            right -= 1
        player = 1 - player
    assert run(x).split() == [str(scores[0]), str(scores[1])]

def test_right_endpoint_choice(run, x):
    v = list(map(int, x.split()))
    cards = v[1:]
    total = [0, 0]
    for turn in range(len(cards)):
        if cards[0] > cards[-1]:
            chosen = cards.pop(0)
        else:
            chosen = cards.pop()
        total[turn & 1] += chosen
    assert run(x).split() == [str(total[0]), str(total[1])]

def test_left_endpoint_choice(run, x):
    from collections import deque
    v = list(map(int, x.split()))
    cards = deque(v[1:])
    sereja = dima = 0
    for turn in range(len(cards)):
        chosen = cards.popleft() if cards[0] > cards[-1] else cards.pop()
        if turn % 2:
            dima += chosen
        else:
            sereja += chosen
    assert run(x).split() == [str(sereja), str(dima)]

def test_odd_length_final_turn(run, x):
    nums = list(map(int, x.split()))[1:]
    lo, hi = 0, len(nums) - 1
    answer = [0, 0]
    for p in range(len(nums)):
        take_left = nums[lo] > nums[hi]
        answer[p % 2] += nums[lo] if take_left else nums[hi]
        if take_left:
            lo += 1
        else:
            hi -= 1
    assert run(x).split() == list(map(str, answer))

def test_score_partition(run, x):
    data = list(map(int, x.split()))
    cards = data[1:]
    i, j = 0, len(cards) - 1
    result = [0, 0]
    for k in range(len(cards)):
        if cards[i] > cards[j]:
            result[k % 2] += cards[i]
            i += 1
        else:
            result[k % 2] += cards[j]
            j -= 1
    assert run(x).split() == [str(result[0]), str(result[1])]

def test_ascending_endpoint_progression(run, x):
    values = list(map(int, x.split()))[1:]
    begin, end = 0, len(values) - 1
    points = [0, 0]
    turn = 0
    while begin <= end:
        if values[begin] > values[end]:
            value = values[begin]
            begin += 1
        else:
            value = values[end]
            end -= 1
        points[turn] += value
        turn = 1 - turn
    assert run(x).split() == [str(points[0]), str(points[1])]

def test_descending_endpoint_progression(run, x):
    cards = list(map(int, x.split()))[1:]
    l, r = 0, len(cards) - 1
    scores = [0, 0]
    for move in range(r + 1):
        if cards[l] < cards[r]:
            scores[move % 2] += cards[r]
            r -= 1
        else:
            scores[move % 2] += cards[l]
            l += 1
    assert run(x).split() == [str(scores[0]), str(scores[1])]

def test_mixed_endpoint_sequence(run, x):
    sequence = list(map(int, x.split()))[1:]
    first, last = 0, len(sequence) - 1
    earned = [0, 0]
    move = 0
    while first <= last:
        pick = max(sequence[first], sequence[last])
        earned[move % 2] += pick
        if pick == sequence[first]:
            first += 1
        else:
            last -= 1
        move += 1
    assert run(x).split() == [str(earned[0]), str(earned[1])]

def test_maximum_length_score(run, x):
    tokens = list(map(int, x.split()))
    n = tokens[0]
    cards = tokens[1:]
    low, high = 0, n - 1
    s = [0, 0]
    for move in range(n):
        if cards[low] > cards[high]:
            s[move & 1] += cards[low]
            low += 1
        else:
            s[move & 1] += cards[high]
            high -= 1
    assert run(x).split() == [str(s[0]), str(s[1])]

