def test_zero(run, x):
    q = list(map(int, x.split()))
    n = q[0]
    a, b, c = q[1:n+1], q[n+1:2*n+1], q[2*n+1:3*n+1]
    dp = [-1] * (1 << n)
    dp[0] = 0
    for mask in range(1 << n):
        if dp[mask] < 0:
            continue
        for i in range(n):
            if not (mask >> i & 1):
                k = (i > 0 and bool(mask >> (i - 1) & 1)) + (i + 1 < n and bool(mask >> (i + 1) & 1))
                dp[mask | (1 << i)] = max(dp[mask | (1 << i)], dp[mask] + (a, b, c)[k][i])
    assert run(x).strip() == str(dp[-1])

