def test_turn_by_turn(run, x):
    vladik, valera = map(int, x.split())
    amount = 1
    while True:
        if amount % 2:
            if vladik < amount:
                expected = 'Vladik'
                break
            vladik -= amount
        else:
            if valera < amount:
                expected = 'Valera'
                break
            valera -= amount
        amount += 1
    assert run(x).strip() == expected

def test_initial_and_alternating(run, x):
    balances = list(map(int, x.split()))
    giver = 0
    amount = 1
    while balances[giver] >= amount:
        balances[giver] -= amount
        giver = 1 - giver
        amount += 1
    expected = ('Vladik', 'Valera')[giver]
    assert run(x).strip() == expected

def test_odd_vladik_turns(run, x):
    a, b = map(int, x.split())
    for amount in range(1, 100000):
        if amount & 1:
            if a < amount:
                expected = 'Vladik'
                break
            a -= amount
        else:
            if b < amount:
                expected = 'Valera'
                break
            b -= amount
    assert run(x).strip() == expected

def test_even_valera_turns(run, x):
    a, b = map(int, x.split())
    amount = 1
    while True:
        available = a if amount % 2 else b
        if available < amount:
            expected = 'Vladik' if amount % 2 else 'Valera'
            break
        if amount % 2:
            a -= amount
        else:
            b -= amount
        amount += 1
    assert run(x).strip() == expected

def test_exact_balance_payment(run, x):
    a, b = map(int, x.split())
    turn = 0
    while True:
        amount = turn + 1
        if turn % 2 == 0:
            if a < amount:
                expected = 'Vladik'
                break
            a -= amount
        else:
            if b < amount:
                expected = 'Valera'
                break
            b -= amount
        turn += 1
    assert run(x).strip() == expected

def test_received_candies_excluded(run, x):
    vladik, valera = map(int, x.split())
    required = 1
    while True:
        if required % 2 == 1:
            if vladik < required:
                expected = 'Vladik'
                break
            vladik = vladik - required
        else:
            if valera < required:
                expected = 'Valera'
                break
            valera = valera - required
        required += 1
    assert run(x).strip() == expected

def test_first_failure(run, x):
    candy = list(map(int, x.split()))
    amount = 1
    player = 0
    while True:
        if candy[player] < amount:
            expected = ('Vladik', 'Valera')[player]
            break
        candy[player] -= amount
        amount += 1
        player = 1 - player
    assert run(x).strip() == expected

def test_large_balances(run, x):
    a, b = map(int, x.split())
    amount = 1
    expected = None
    while expected is None:
        if amount % 2 == 1:
            if a < amount:
                expected = 'Vladik'
            else:
                a -= amount
        else:
            if b < amount:
                expected = 'Valera'
            else:
                b -= amount
        amount += 1
    assert run(x).strip() == expected

def test_asymmetric_balances(run, x):
    a, b = map(int, x.split())
    needed = 1
    while True:
        if needed % 2:
            payer, name = a, 'Vladik'
        else:
            payer, name = b, 'Valera'
        if payer < needed:
            expected = name
            break
        if needed % 2:
            a -= needed
        else:
            b -= needed
        needed += 1
    assert run(x).strip() == expected

def test_output_winner(run, x):
    a, b = map(int, x.split())
    amount = 1
    while True:
        if amount % 2 == 1:
            if a < amount:
                expected = 'Vladik'
                break
            a -= amount
        else:
            if b < amount:
                expected = 'Valera'
                break
            b -= amount
        amount += 1
    assert run(x).strip() == expected

def test_turn_by_turn(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    need = 1
    while True:
        if need % 2:
            if a < need:
                winner = 'Vladik'
                break
            a -= need
        else:
            if b < need:
                winner = 'Valera'
                break
            b -= need
        need += 1
    assert out == winner

def test_odd_even_totals(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    m = 1
    while True:
        if a < m * m:
            winner = 'Vladik'
            break
        if b < m * (m + 1):
            winner = 'Valera'
            break
        m += 1
    assert out == winner

def test_alternating_stock(run, x):
    v, w = map(int, x.split())
    out = run(x).strip()
    gift = 1
    v_turn = True
    while True:
        if v_turn:
            if v < gift:
                winner = 'Vladik'
                break
            v -= gift
        else:
            if w < gift:
                winner = 'Valera'
                break
            w -= gift
        gift += 1
        v_turn = not v_turn
    assert out == winner

def test_vladik_odd_turns(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    m = 1
    while True:
        if a < m * m:
            winner = 'Vladik'
            break
        if b < m * (m + 1):
            winner = 'Valera'
            break
        m += 1
    assert out == winner

def test_valera_even_turns(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    amount = 1
    while True:
        if amount % 2 == 1:
            if a < amount:
                winner = 'Vladik'
                break
            a -= amount
        else:
            if b < amount:
                winner = 'Valera'
                break
            b -= amount
        amount += 1
    assert out == winner

def test_first_unaffordable(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    turn = 1
    while True:
        stock = a if turn % 2 else b
        if stock < turn:
            winner = 'Vladik' if turn % 2 else 'Valera'
            break
        if turn % 2:
            a -= turn
        else:
            b -= turn
        turn += 1
    assert out == winner

def test_square_pronic_boundary(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    count = 1
    while True:
        v_required = count ** 2
        w_required = count * (count + 1)
        if a < v_required:
            winner = 'Vladik'
            break
        if b < w_required:
            winner = 'Valera'
            break
        count += 1
    assert out == winner

def test_required_amount_progression(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    for required in range(1, 100000):
        if required & 1:
            if a < required:
                winner = 'Vladik'
                break
            a -= required
        else:
            if b < required:
                winner = 'Valera'
                break
            b -= required
    assert out == winner

def test_chronological_failure(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    m = 1
    while True:
        if m * m > a:
            winner = 'Vladik'
            break
        if m * (m + 1) > b:
            winner = 'Valera'
            break
        m += 1
    assert out == winner

def test_exact_winner_token(run, x):
    a, b = map(int, x.split())
    out = run(x).strip()
    required = 1
    while True:
        if required % 2 == 1:
            if required > a:
                expected = 'Vladik'
                break
            a = a - required
        else:
            if required > b:
                expected = 'Valera'
                break
            b = b - required
        required += 1
    assert out == expected

def test_output_lines(run, x):
